	name := os.Getenv(logging.LogLevelEnvVar)
	if name == "" {
		if s, err := settings.Load(ctx); err == nil {
			name = s.LogLevel
		}
	}
	level, ok := logging.ParseLevel(name)
	if !ok {
		fmt.Fprintf(os.Stderr, "[entire] Warning: invalid log level %q, defaulting to INFO\n", name)
	}

